python3 - <<'E'
p='tests/unit/providers/alma/test_alma.py'
s=open(p).read()
s=s.replace("mock_git_clone, helpers):","mock_git_clone, helpers, auto_fake_fixdate_finder):")
s=s.replace("def test_modularity_parsing(helpers):","def test_modularity_parsing(helpers, auto_fake_fixdate_finder):")
s+='''

def test_fix_dates_use_utc_published_and_library_clones(helpers, auto_fake_fixdate_finder):
    workspace = helpers.provider_workspace_helper(name=Provider.name())
    parser = Parser(ws=workspace, fixdater=auto_fake_fixdate_finder)
    entry = {
        "id": "ALSA-2019:3706",
        "published": "2019-12-10T23:30:00-05:00",
        "affected": [
            {
                "package": {"name": "lua", "ecosystem": "AlmaLinux:8"},
                "ranges": [{"type": "ECOSYSTEM", "events": [{"introduced": "0"}, {"fixed": "5.3.4-11.el8"}]}],
            }
        ],
    }
    _, _, record = parser._normalize(entry, "8")
    assert [a["package"]["name"] for a in record["affected"]] == ["lua", "lua-libs"]
    for a in record["affected"]:
        assert a["ranges"][0]["database_specific"]["anchore"]["fixes"] == [
            {"version": "5.3.4-11.el8", "date": "2019-12-11", "kind": "advisory"}
        ]
    assert record["database_specific"]["anchore"] == {"record_type": "advisory"}
'''
open(p,'w').write(s)
E
